describe('Dashboard Sidebar to Bottom Nav Bar Transition on Mobile', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should display sidebar as bottom nav bar on mobile viewport', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/dashboard/sidebar').as('sidebarData');
      cy.wait('@sidebarData');
    });

    // Verify sidebar is visible
    cy.get('[data-testid="sidebar-toggle"]').should('be.visible');
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Verify sidebar has correct class for mobile
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'mobile-nav');

    // Verify sidebar items are present
    cy.get('[data-testid="sidebar-item"]').should('have.length.greaterThan', 0);

    // Verify navigation links are clickable
    cy.get('[data-testid="sidebar-item"]').first().click();
    cy.url().should('include', '/dashboard/settings');

    // Verify sidebar is hidden when toggled
    cy.get('[data-testid="sidebar-toggle"]').click();
    cy.get('[data-testid="sidebar-menu"]').should('not.exist');

    // Verify main content is visible
    cy.get('[data-testid="main-content"]').should('be.visible');
  });

  it('should handle edge case where sidebar is already in bottom nav bar state', () => {
    // Set viewport to mobile
    cy.viewport('iphone-x').then(() => {
      cy.intercept('GET', '/api/dashboard/sidebar').as('sidebarData');
      cy.wait('@sidebarData');
    });

    // Verify sidebar is initially visible
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Verify sidebar has correct class for mobile
    cy.get('[data-testid="sidebar-menu"]').should('have.class', 'mobile-nav');

    // Verify sidebar items are present
    cy.get('[data-testid="sidebar-item"]').should('have.length.greaterThan', 0);

    // Verify navigation links are clickable
    cy.get('[data-testid="sidebar-item"]').first().click();
    cy.url().should('include', '/dashboard/settings');

    // Verify sidebar is still visible after toggling
    cy.get('[data-testid="sidebar-toggle"]').click();
    cy.get('[data-testid="sidebar-menu"]').should('be.visible');

    // Verify main content is still visible
    cy.get('[data-testid="main-content"]').should('be.visible');
  });
});
